import contextlib
import io
import json
import os
import sys
import traceback

HERE = os.path.dirname(os.path.abspath(__file__))


def emit(obj):
    # Print the single final JSON object on stdout.
    sys.stdout.write(json.dumps(obj) + '\n')
    sys.stdout.flush()


def load_candidate():
    # Read the candidate source saved verbatim from the fenced block and
    # execute it in an isolated namespace. Incidental output is captured.
    with open(os.path.join(HERE, 'block-0.txt'), encoding='utf-8') as f:
        src = f.read()
    ns = {'__name__': 'candidate_module'}
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
        exec(compile(src, 'block-0.txt', 'exec'), ns)
    fn = ns.get('tuple_to_dict')
    if not callable(fn):
        raise RuntimeError('tuple_to_dict is not defined by the candidate source')
    return fn


def normalize(result):
    # Adapter normalization from the contract: a dict becomes a list of
    # [key, value] pairs sorted by key. Any other return value is passed
    # through unchanged so it can be compared against output_schema.
    if isinstance(result, dict):
        pairs = [[k, v] for k, v in result.items()]
        try:
            pairs.sort(key=lambda p: p[0])
        except TypeError:
            pass
        return pairs
    return result


def main():
    try:
        fn = load_candidate()
        with open(os.path.join(HERE, 'inputs.json'), encoding='utf-8') as f:
            cases = json.load(f)
        if not isinstance(cases, list):
            raise ValueError('inputs.json must contain a list')
    except Exception as e:
        emit({'results': [], 'harness_error': 'setup failed: %s: %s' % (type(e).__name__, e)})
        return

    results = []
    for case in cases:
        entry_id = case.get('id') if isinstance(case, dict) else None
        try:
            tup = tuple(case.get('input'))
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
                res = fn(tup)
            actual = normalize(res)
            json.dumps(actual)
            results.append({'id': entry_id, 'actual': actual})
        except Exception as e:
            results.append({'id': entry_id, 'error': '%s: %s' % (type(e).__name__, e)})

    emit({'results': results})


if __name__ == '__main__':
    try:
        main()
    except Exception as e:
        emit({'results': [], 'harness_error': 'unexpected: %s: %s' % (type(e).__name__, traceback.format_exc(limit=3))})
